const pillars = [
  {id:'product',n:'P1',name:'Sản phẩm / Dịch vụ',vn:'Sản phẩm & dịch vụ',tag:'Bán đúng trải nghiệm cho đúng nhu cầu',kpi:['Hành khách/lượt & hệ số lấp đầy','Lãi góp/chuyến','LNST/xe/tháng','Tỷ lệ lỗi/khiếu nại'],driver:['Cấu hình xe & sức chứa','Tuyến × giờ chạy','Mức dịch vụ & hàng hóa','Cơ cấu sản phẩm'],actions:['Tách hiệu quả kinh tế theo Tuyến × Sản phẩm × Chuyến × Xe.','Xếp Nhân rộng / Bảo vệ / Sửa / Dừng bằng lãi góp, LNST/xe và tỷ suất sinh lời trên vốn đầu tư.','Thử đổi cấu hình/công suất trước khi thêm xe.'],question:'Sản phẩm nào tạo nhiều lợi nhuận trên một đồng vốn nhất — và vì sao?',evidence:'Tệp KHKD có R24, R34C, MOCHA 10 và MOCHA 12; hiệu quả kinh tế khác nhau mạnh dù cùng ngành.'},
  {id:'price',n:'P2',name:'Giá',vn:'Giá',tag:'Tối ưu doanh thu thực thu, không chỉ giá niêm yết',kpi:['Doanh thu thực thu/khách','Giảm giá/khách','Lãi góp/khách','Độ co giãn theo khung giờ'],driver:['Mức sẵn lòng chi trả','Cao điểm / thấp điểm','Hàng rào giá','Chính sách đổi/hủy'],actions:['Tách giá niêm yết, giảm giá và thực thu.','Thử nghiệm A/B theo khung giờ; giữ nhóm đối chứng.','Dừng khuyến mại nếu khách tăng không bù phần biên lợi nhuận đã mất.'],question:'Tăng giá 5% làm lượng khách giảm bao nhiêu, và lãi góp cuối cùng đổi thế nào?',evidence:'Nguồn 7P+F nội bộ nêu “áp dụng mô hình giá linh hoạt”; tệp KHKD phân giá theo sản phẩm/thời điểm.'},
  {id:'place',n:'P3',name:'Phân phối',vn:'Phân phối',tag:'Đưa công suất đến đúng điểm bán',kpi:['Lãi góp/khách/kênh','Tỷ lệ chuyển đổi','Hoa hồng/chi phí có khách mới','Tỷ trọng kênh trực tiếp & khách trung thành'],driver:['Ứng dụng, trang web, tổng đài','Kênh bán vé trực tuyến/đại lý','Điểm trung chuyển & điểm đón','Bán chéo'],actions:['Tính doanh thu sau chi phí kênh.','Tách khách tăng thêm khỏi khách chỉ chuyển kênh.','Dùng kênh bán vé trực tuyến để hứng nhu cầu, rồi chuyển đổi sang khách hàng thành viên.'],question:'Kênh nào mang khách tăng thêm có lãi góp tốt nhất, không chỉ nhiều lượt đặt nhất?',evidence:'Bảng tính 7P+F liệt kê Vexere, Zalo, Momo, Payoo, khách sạn và mã QR bán hàng.'},
  {id:'promotion',n:'P4',name:'Xúc tiến',vn:'Xúc tiến',tag:'Kích cầu có kiểm chứng',kpi:['Khách tăng thêm','Lãi góp từ khuyến mại','Chi phí/khách mới hoạt động','Tỷ lệ mua lại'],driver:['Ưu đãi & nội dung sáng tạo','Phân khúc mục tiêu','Thời điểm & địa bàn','Kênh sở hữu / trả phí / đối tác'],actions:['Đặt đường cơ sở trước chiến dịch.','Đo khách tăng thêm và phần biên lợi nhuận hy sinh.','Nhân rộng theo nhóm khách; dừng nếu chỉ trợ giá khách sẵn có.'],question:'Nếu bỏ khuyến mại, bao nhiêu khách vẫn mua? Phần còn lại có đủ lãi góp không?',evidence:'Nguồn nội bộ dùng giá linh hoạt, bán nhanh có thời hạn, truyền thông theo vùng và liên kết khách hàng trung thành.'},
  {id:'people',n:'P5',name:'Con người',vn:'Con người',tag:'Năng lực và hành vi tại điểm chạm',kpi:['Doanh thu/lao động tương đương toàn thời gian','Tuân thủ dịch vụ','Điểm đánh giá/mức sẵn sàng giới thiệu','Giờ lái & an toàn'],driver:['Lái xe & trung tâm điều hành','Tổng đài/chăm sóc khách hàng','Bán hàng/tiếp thị','Đối tác & đại lý'],actions:['Gắn đào tạo với quan sát hành vi và kết quả.','Chốt người chịu trách nhiệm theo chức năng; VP TGĐ chỉ theo dõi và gỡ nghẽn.','Bảo vệ quyền phản ánh rủi ro an toàn.'],question:'Hành vi nào của ai đang kéo chỉ số xuống, và họ có đủ quyền/công cụ để sửa không?',evidence:'Nguồn nội bộ nêu tuyển lái xe, bán đúng kịch bản và tuân thủ quy trình dịch vụ.'},
  {id:'process',n:'P6',name:'Quy trình',vn:'Quy trình',tag:'Giảm ma sát, chờ đợi và chạy rỗng',kpi:['Tỷ lệ đúng giờ','Thời gian quay đầu','Tỷ lệ km chạy rỗng','Thời gian ngừng hoạt động & tỷ lệ hoàn tất đặt vé'],driver:['Lịch xe & điều độ','Đặt vé → phục vụ','Bảo dưỡng','Bàn giao & xử lý sự cố'],actions:['Vẽ lịch 24 giờ cho từng xe.','Bóc chuyến có doanh thu / chờ / chạy rỗng / ngừng hoạt động.','Chuẩn hóa, số hóa rồi mới tự động hóa.'],question:'Một ngày của xe mất bao nhiêu giờ cho hoạt động không tạo doanh thu?',evidence:'Nguồn 7P+F đặt trọng tâm số hóa/tự động hóa và quy trình dịch vụ, chốt đơn.'},
  {id:'physical',n:'P7',name:'Bằng chứng hữu hình',vn:'CSVC & bằng chứng hữu hình',tag:'Biến lời hứa thành trải nghiệm thấy được',kpi:['Tỷ lệ xe sẵn sàng','Điểm chạm đạt chuẩn','Chi phí điểm phục vụ/chuyến','Sự cố cơ sở vật chất'],driver:['Xe & ghế','Điểm trung chuyển/phòng chờ','Đồng phục/nhận diện','Giấy phép & hợp đồng'],actions:['Rà soát điểm chạm theo hành trình khách.','Đo hiệu quả cơ sở vật chất bằng tỷ lệ chuyển đổi, chất lượng dịch vụ và chi phí/lượt.','Tách điều kiện pháp lý khỏi mục tiêu thương hiệu.'],question:'Bằng chứng hữu hình nào thực sự tăng tin cậy hoặc tỷ lệ chuyển đổi, và cái nào chỉ làm đẹp?',evidence:'Nguồn nội bộ gộp Bằng chứng hữu hình + pháp lý: quầy nhỏ, điểm trung chuyển, quầy vé, giấy phép, hợp đồng sân bay.'},
  {id:'finance',n:'F',name:'Tài chính',vn:'Tài chính',tag:'Lớp kiểm chứng xuyên suốt 7P',finance:true,kpi:['Lãi góp/chuyến & /km','LNST/xe/tháng','Tỷ suất sinh lời trên vốn đầu tư/sản phẩm','Tổng chi phí sở hữu/km & dòng tiền'],driver:['Doanh thu thực thu & sản lượng','Biến phí/định phí','Vốn đầu tư & khấu hao','Nợ vay & chi phí vốn'],actions:['Nối mọi chỉ số vận hành về lợi nhuận và vốn.','Duyệt xe mới bằng tỷ suất sinh lời tăng thêm trên vốn đầu tư, có phương án thuê/hợp tác.','Đối soát báo cáo lãi lỗ sản phẩm với báo cáo tổng trước quyết định khó đảo ngược.'],question:'Sau cùng, phương án tạo thêm bao nhiêu dòng tiền/lợi nhuận sau thuế trên mỗi đồng vốn và rủi ro bất lợi là gì?',evidence:'Trong bảng tính “Chiến thuật 7P+F”, Tài chính là cột ngân sách xuyên suốt; tệp KHKD tạo báo cáo lãi lỗ thu nhỏ theo sản phẩm.'}
];

const grid=document.getElementById('pillarGrid'), detail=document.getElementById('pillarDetail');
pillars.forEach((p,i)=>{const b=document.createElement('button');b.className=`pillar-card ${p.finance?'finance':''}`;b.dataset.id=p.id;b.innerHTML=`<span class="num">${p.n}</span><em>↗</em><strong>${p.vn}</strong><p>${p.tag}</p>`;b.onclick=()=>showPillar(p,b);grid.appendChild(b);});
function showPillar(p,b){document.querySelectorAll('.pillar-card').forEach(x=>x.classList.remove('active'));b.classList.add('active');detail.innerHTML=`<div class="detail-grid"><div><p class="eyebrow">${p.n} · ${p.name}</p><h3>${p.vn}</h3><p>${p.tag}</p><p class="data-caption"><span class="dot verified"></span>${p.evidence}</p></div><div><h4>CHỈ SỐ & BIẾN SỐ</h4><ul>${p.kpi.map(x=>`<li><b>${x}</b></li>`).join('')}</ul><h4>BIẾN SỐ CHÍNH</h4><ul>${p.driver.map(x=>`<li>${x}</li>`).join('')}</ul></div><div><h4>HÀNH ĐỘNG ĐIỀU CHỈNH</h4><ol>${p.actions.map(x=>`<li>${x}</li>`).join('')}</ol><div class="question-box"><b>Câu hỏi quản trị</b><br>${p.question}</div></div></div>`;detail.classList.add('visible');if(window.innerWidth<700)detail.scrollIntoView({behavior:'smooth',block:'start'});}
showPillar(pillars[0],grid.firstChild);

document.querySelectorAll('.segmented button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.segmented button').forEach(x=>x.classList.remove('active'));b.classList.add('active');const layer=b.dataset.layer;document.querySelectorAll('.source-layer').forEach(x=>x.classList.toggle('hidden-layer',layer==='interpretation'));document.querySelectorAll('.interpretation-layer').forEach(x=>x.classList.toggle('hidden-layer',layer==='source'));});

const sliders={load:document.getElementById('load'),yield:document.getElementById('yield'),trip:document.getElementById('trip'),fuel:document.getElementById('fuel')};
function updateScenario(){const l=+sliders.load.value/70,y=+sliders.yield.value/100,t=+sliders.trip.value/180,f=+sliders.fuel.value/100;document.getElementById('loadOut').value=sliders.load.value+'%';document.getElementById('yieldOut').value=sliders.yield.value;document.getElementById('tripOut').value=(sliders.trip.value/100).toLocaleString('vi-VN',{minimumFractionDigits:2});document.getElementById('fuelOut').value=sliders.fuel.value;const revenue=100*l*y*t;const index=Math.max(0,Math.round(revenue-(f-1)*29));const delta=index-100;document.getElementById('econIndex').textContent=index;document.getElementById('econDelta').textContent=delta===0?'Mức cơ sở':`${delta>0?'+':''}${delta} điểm so với cơ sở`;let rec=[];if(l<.9)rec.push('Chẩn đoán khung giờ và gom lịch trước khi chi thêm tiền kích cầu.');if(y<.9)rec.push('Kiểm tra thất thoát do giảm giá và lãi góp/khách.');if(t<.85)rec.push('Vẽ lịch 24 giờ của xe để bóc thời gian chờ, chạy rỗng và ngừng hoạt động.');if(f>1.1)rec.push('Chuẩn hóa nhiên liệu theo tuyến × xe × lái xe; kiểm tra chạy không tải và bảo dưỡng.');if(!rec.length)rec.push('Kịch bản không có tín hiệu đỏ rõ ràng; kiểm tra tính bền vững và tỷ suất sinh lời trên vốn đầu tư trước khi nhân rộng.');document.getElementById('recommendation').innerHTML=`<b>Ưu tiên kiểm tra</b><br>${rec.join(' ')}`;}
Object.values(sliders).forEach(s=>s.oninput=updateScenario);document.getElementById('resetScenario').onclick=()=>{sliders.load.value=70;sliders.yield.value=100;sliders.trip.value=180;sliders.fuel.value=100;updateScenario()};updateScenario();

const cards=[['HỆ SỐ LẤP ĐẦY','Hệ số lấp đầy tăng có luôn tốt?','Không. Nếu tăng nhờ giảm giá quá sâu, lãi góp có thể giảm. Luôn đọc cùng doanh thu thực thu/khách và lãi góp/chuyến.'],['NĂNG SUẤT TÀI SẢN','Vì sao MOCHA 10 đáng chẩn đoán?','10 xe nhưng LNST/xe chỉ khoảng 3,5 triệu/tháng. Điểm nghi vấn là năng suất tài sản, không chỉ thiếu khách.'],['GIÁ','Chỉ số giá quan trọng nhất là gì?','Doanh thu thực thu trên mỗi hành khách — sau giảm giá và điều chỉnh.'],['PHÂN PHỐI','Kênh bán nhiều khách nhất có phải tốt nhất?','Chưa chắc. Xếp kênh bằng lãi góp/khách sau hoa hồng, chi phí có khách mới và phần khách chỉ dịch chuyển kênh.'],['TÀI CHÍNH','Khi nào nên thêm xe?','Khi đội xe hiện hữu đã được tối ưu và ROIC tăng thêm của mua xe tốt hơn thuê/hợp tác, kể cả trong kịch bản bất lợi.'],['QUY TRÌNH','Một xe không chạy vẫn tốn gì?','Khấu hao, lãi vay, bảo hiểm, bãi đỗ và một phần nhân sự/quản trị. Vì thế thời gian ngừng hoạt động là chi phí thật.']];
let ci=0,flipped=false;function renderCard(){const c=cards[ci];document.getElementById('cardKicker').textContent=c[0];document.getElementById('cardFront').textContent=c[1];document.getElementById('cardBack').textContent=c[2];document.getElementById('cardCount').textContent=`${ci+1} / ${cards.length}`;document.getElementById('flashcard').classList.toggle('flipped',flipped)}document.getElementById('flashcard').onclick=()=>{flipped=!flipped;renderCard()};document.getElementById('prevCard').onclick=()=>{ci=(ci-1+cards.length)%cards.length;flipped=false;renderCard()};document.getElementById('nextCard').onclick=()=>{ci=(ci+1)%cards.length;flipped=false;renderCard()};renderCard();

document.querySelectorAll('.learn-tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.learn-tabs button,.tab-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active')});
const quiz=[{q:'Đơn vị kinh tế nên được phân tích gần nhất là?',o:['Công ty','Tuyến × sản phẩm × chuyến × xe','Phòng ban'],a:1,e:'Đây là lát cắt đủ gần để thấy khác biệt về nhu cầu, giá, công suất và tài sản.'},{q:'Hệ số lấp đầy thấp, hành động đầu tiên?',o:['Giảm giá toàn tuyến','Tách theo chuyến/giờ/ngày','Mua thêm xe'],a:1,e:'Bình quân tuyến che giấu chuyến đầy và chuyến rỗng.'},{q:'Chỉ số nào nối tốt nhất giá với lợi nhuận ngắn hạn?',o:['Giá niêm yết','Lãi góp/khách','Số bài quảng cáo'],a:1,e:'Lãi góp phản ánh doanh thu thực thu sau biến phí liên quan.'},{q:'Muốn so xe động cơ đốt trong, xe lai và xe điện nên ưu tiên?',o:['Nhiên liệu/km','Giá mua xe','Tổng chi phí sở hữu/km tạo doanh thu'],a:2,e:'Tổng chi phí sở hữu gom vốn, năng lượng, bảo dưỡng, thời gian ngừng hoạt động và giá trị còn lại.'},{q:'Vai trò Tài chính trong 7P+F?',o:['Chỉ lập ngân sách tiếp thị','Lớp kiểm chứng xuyên suốt giá trị và vốn','Thay người chịu trách nhiệm vận hành'],a:1,e:'Tài chính biến hành động 7P thành hiệu quả kinh tế và kỷ luật vốn.'}];let qi=0,score=0;function renderQuiz(){const app=document.getElementById('quizApp');if(qi>=quiz.length){app.innerHTML=`<div class="quiz-question"><p class="eyebrow">HOÀN THÀNH</p><h3>${score}/${quiz.length} câu đúng</h3><p>${score>=4?'Bạn đã nắm khá chắc logic biến số tác động. Hãy thử tình huống quản trị.':'Xem lại bản đồ 7P+F rồi làm lại để nối chỉ số với hiệu quả kinh tế.'}</p><button class="button primary" id="retryQuiz">Làm lại</button></div>`;document.getElementById('retryQuiz').onclick=()=>{qi=0;score=0;renderQuiz()};return}const q=quiz[qi];app.innerHTML=`<div class="quiz-question"><p class="eyebrow">CÂU ${qi+1}/${quiz.length}</p><h3>${q.q}</h3><div class="quiz-options">${q.o.map((x,i)=>`<button data-answer="${i}">${x}</button>`).join('')}</div><div id="quizFeedback"></div></div>`;app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.answer===q.a;if(ok)score++;app.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);document.getElementById('quizFeedback').innerHTML=`<div class="quiz-feedback"><b>${ok?'Đúng.':'Chưa đúng.'}</b> ${q.e}<br><button class="button secondary" id="nextQuiz">Câu tiếp</button></div>`;document.getElementById('nextQuiz').onclick=()=>{qi++;renderQuiz()}})}renderQuiz();

document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{const ok=b.dataset.case==='right';document.getElementById('caseFeedback').innerHTML=`<div class="quiz-feedback"><b>${ok?'Đúng hướng.':'Chưa nên.'}</b> ${ok?'Hệ số lấp đầy khá nhưng vòng quay tài sản thấp; cần bóc lãi góp và thời gian xe trước khi chọn đòn bẩy.':'Hành động này chưa chứng minh được nguyên nhân gốc và có thể làm tăng chi phí hoặc khóa thêm vốn.'}</div>`});
document.getElementById('modeToggle').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('hvxt-theme',document.body.classList.contains('dark')?'dark':'light')};if(localStorage.getItem('hvxt-theme')==='dark')document.body.classList.add('dark');
